parameters.jsCode:
// One row per place, with the e-mails and social profiles found on its website.
return $input.all()
  .filter((item) => item.json.found !== false)
  .map(({ json: p }) => ({
    json: {
      name: p.name,
      category: p.category,
      email: p.email ?? null,
      allEmails: (p.emails || []).join(', '),
      phone: p.phone,
      website: p.website,
      facebook: p.facebookUrl ?? null,
      instagram: p.instagramUrl ?? null,
      linkedin: p.linkedinUrl ?? null,
      address: p.address,
      city: p.city,
      rating: p.rating,
      reviewsCount: p.reviewsCount,
      contactStatus: p.contactStatus ?? null,
      googleMapsUrl: p.googleMapsUrl,
      searchQuery: p.searchQuery,
    },
  }));
